import{_ as e,c as o,o as t,ah as n}from"./chunks/framework.DX1DJjtl.js";const p=JSON.parse('{"title":"Canvas and Hosted Programs","description":"","frontmatter":{},"headers":[],"relativePath":"guides/building-interfaces/canvas-and-programs.md","filePath":"guides/building-interfaces/canvas-and-programs.md","lastUpdated":1785349141000}'),r={name:"guides/building-interfaces/canvas-and-programs.md"};function s(i,a,l,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="canvas-and-hosted-programs" tabindex="-1">Canvas and Hosted Programs <a class="header-anchor" href="#canvas-and-hosted-programs" aria-label="Permalink to &quot;Canvas and Hosted Programs&quot;">​</a></h1><p>This topic is now split into two focused guides:</p><ul><li><a href="./canvas.html">Canvas</a> — draw custom surfaces owned by the Basalt application.</li><li><a href="./hosted-programs.html">Hosted Programs</a> — embed a complete CC program with its own terminal and event loop.</li></ul><h2 id="which-one-do-i-need" tabindex="-1">Which One Do I Need? <a class="header-anchor" href="#which-one-do-i-need" aria-label="Permalink to &quot;Which One Do I Need?&quot;">​</a></h2><p>Choose Canvas when:</p><ul><li>the model already belongs to your Basalt application;</li><li>you need custom cells, charts, maps, editors, or heatmaps;</li><li>input should directly modify the same model that is drawn.</li></ul><p>Choose Program when:</p><ul><li>the child is already a complete terminal application;</li><li>it needs <code>term</code>, <code>os.pullEvent()</code>, timers, or its own redirects;</li><li>the host should control focus, size, lifecycle, and error handling.</li></ul><p>Do not recreate a complete terminal API inside Canvas. Do not launch a separate program when a small draw callback is enough.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><ul><li>Start with <a href="./canvas.html">Canvas</a>.</li><li>Continue with <a href="./hosted-programs.html">Hosted Programs</a>.</li><li>Use <a href="./../development/performance-tuning.html">Performance Tuning</a> for dense or frequently changing surfaces.</li></ul>',11)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
